import React, { useState, useEffect } from 'react';
// Import necessary components from react-router-dom
// Remove BrowserRouter, Routes, Route as they are handled by createBrowserRouter/RouterProvider
import { Link, useNavigate, useLocation, Outlet } from 'react-router-dom'; // Import Outlet

// Assuming Tailwind CSS is set up in your project
// Assuming components are in the ./components directory as per your import paths
import Navbar from './components/Navbar'; // Corrected import path
// No need to import other page components here, as they are rendered by the router


// Placeholder function to simulate fetching download links and thumbnail
// In a real app, this would make an API call to your backend
// This function remains in App (or a shared context/hook) because it's triggered
// from the HomePage but the results are needed by the DownloadPage.
const fetchDownloadOptions = async (url) => {
  console.log('Fetching options for:', url);
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 1500));

  // Basic URL validation
  if (!url || !url.trim()) {
      throw new Error('Please enter a Facebook video URL.');
  }
   if (!url.includes('facebook.com')) {
       throw new Error('Please enter a valid Facebook URL.');
   }

  // Note: Your provided fetchDownloadOptions returns an array of options directly,
  // not an object with thumbnailUrl and options. Adjusting return structure here
  // to match the expected structure for the DownloadPage component.
  if (url.includes('facebook.com/watch/') || url.includes('facebook.com/videos/')) {
    // Simulate successful response with download options AND a placeholder thumbnail
    return {
        thumbnailUrl: 'https://placehold.co/400x225/E5E7EB/1F2937?text=Video+Thumbnail', // Placeholder thumbnail URL
        options: [
            { quality: 'HD', url: '#', format: 'MP4', size: 'Approx. 50MB' }, // Replace '#' with actual download links
            { quality: 'SD', url: '#', format: 'MP4', size: 'Approx. 20MB' }, // Replace '#' with actual download links
            // Add more options here if your backend provides them
        ]
    };
  } else {
    throw new Error('Could not fetch video from this URL. Please check the URL or try again.');
  }
};


// App component now acts as a Layout component, rendering Navbar, Footer, and an Outlet
// for the content defined by the router.
function App() {
    // State to manage the input URL for the homepage downloader
    // This state needs to be accessible by HomePage
    const [videoUrl, setVideoUrl] = useState('');
    // State to manage dark mode for the entire app
    const [darkMode, setDarkMode] = useState(false);
    // State for loading status on the homepage
    // This state needs to be accessible by HomePage
    const [isLoading, setIsLoading] = useState(false);
    // State for error messages on the homepage
    // This state needs to be accessible by HomePage
    const [error, setError] = useState(null);
    // State to store download options specifically for the results page
    // This state needs to be accessible by DownloadPage
    const [resultsOptions, setResultsOptions] = useState([]); // Array<{quality, url, format, size}>
    // State to store the thumbnail URL for the results page
    // This state needs to be accessible by DownloadPage
    const [resultsThumbnailUrl, setResultsThumbnailUrl] = useState(null); // String | null

    // React Router hooks for navigation and location
    const navigate = useNavigate();
    const location = useLocation();
    const currentPage = location.pathname; // Determine current page based on path

    // Effect to check local storage for dark mode preference on mount
    useEffect(() => {
        const isDarkMode = localStorage.getItem('darkMode') === 'true';
        setDarkMode(isDarkMode);
        // Apply dark mode class to the body or html element
        if (isDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, []); // Empty dependency array means this effect runs only once on mount

    // Function to handle dark mode toggle
    const toggleDarkMode = () => {
        const newDarkMode = !darkMode;
        setDarkMode(newDarkMode);
        // Save preference to local storage
        localStorage.setItem('darkMode', newDarkMode);
        // Apply/remove dark mode class
        if (newDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    };

    // Function to handle input change on the homepage
    // This function needs to be passed to HomePage
    const handleInputChange = (event) => {
        setVideoUrl(event.target.value);
        // Clear error when user starts typing again
        if (error) {
            setError(null);
        }
         // Note: Clearing resultsOptions and navigating is now handled after successful fetch
         // or when navigating away via Link components, not just on input change
    };

    // Function to handle download button click on the homepage
    // Fetches data and then navigates to the download results page
    // This function needs to be passed to HomePage
    const handleDownloadAndNavigate = async () => {
        setError(null); // Clear previous errors
        setResultsOptions([]); // Clear previous results
        setResultsThumbnailUrl(null); // Clear previous thumbnail
        setIsLoading(true);

        try {
            const result = await fetchDownloadOptions(videoUrl); // Calls the placeholder

            // On success, store options and thumbnail
            setResultsOptions(result.options); // Assuming fetchDownloadOptions returns { options: [...], thumbnailUrl: '...' }
            setResultsThumbnailUrl(result.thumbnailUrl); // Assuming fetchDownloadOptions returns { options: [...], thumbnailUrl: '...' }


            // Navigate to the results page AFTER setting state
            navigate('/download'); // Use the navigate function from react-router-dom

        } catch (err) {
            // On error, stay on the homepage and display the error
            setError(err.message || 'An unexpected error occurred.');
            setResultsOptions([]); // Ensure no stale options are shown
            setResultsThumbnailUrl(null); // Ensure no stale thumbnail is shown
            // No navigation needed on error, stay on home
        } finally {
            setIsLoading(false);
        }
    };

    // State and handlers related to fetching and navigation are managed here in App (Layout)
    // and will be passed down to the components rendered by the router (HomePage, DownloadPage).
    // This can be done via Context API or by passing props directly in the Route element.
    // Passing props in the Route element is simpler for this example and aligns with HomePage signature.

    return (
        // Main container applying dark mode class based on state
        // Remove BrowserRouter wrapper here - it should be in index.js with RouterProvider
        <div className={`min-h-screen bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-200 flex flex-col items-center transition-colors duration-300`}>

            {/* Navigation Bar - Pass dark mode state and toggle function */}
            {/* Navbar links will use react-router-dom's Link component */}
            {/* Pass currentPage for active state styling */}
            {/* Navbar needs to be updated to use react-router-dom Link */}
            <Navbar
                darkMode={darkMode}
                toggleDarkMode={toggleDarkMode}
                currentPage={currentPage} // Pass current path
            />

            {/* Main content area where routed components will be rendered */}
            {/* Use Outlet to render the matched route component */}
            <div className="flex-grow w-full flex justify-center">
                 {/* The component matched by the router (e.g., HomePage, DownloadPage) renders here */}
                 {/* State and handlers managed in App need to be passed down to these components */}
                 {/* This is done in the routes configuration (routes.js) */}
                 {/* For example, in routes.js: element: <HomePage videoUrl={videoUrl} handleInputChange={handleInputChange} ... /> */}
                 {/* Or use React Context */}
                 {/* For simplicity in this example, we assume state/handlers are passed down via props in routes.js */}
                 <Outlet context={{ videoUrl, setVideoUrl, handleInputChange, handleDownloadAndNavigate, isLoading, error, resultsOptions, resultsThumbnailUrl, darkMode, toggleDarkMode, navigate }} /> {/* Using Outlet context to pass data */}
            </div>


            {/* Footer - Appears on all pages */}
            {/* Footer links will use react-router-dom's Link component */}
            {/* Footer links need to be updated to use react-router-dom Link */}
            <footer className="text-center mt-8 mb-4 text-gray-600 dark:text-gray-400 text-sm">
                {/* Using react-router-dom Link components */}
                {/* Assuming Link is imported from react-router-dom */}
                <Link to="/privacy" className="hover:underline mx-2 text-inherit">Privacy Policy</Link> |
                <Link to="/term-and-service" className="hover:underline mx-2 text-inherit">Terms of Service</Link> | {/* Corrected path */}
                <Link to="/about" className="hover:underline mx-2 text-inherit">About Us</Link> | {/* Corrected path */}
                <Link to="/contact-us" className="hover:underline mx-2 text-inherit">Contact Us</Link> | {/* Corrected path */}
                <Link to="/faq" className="hover:underline mx-2 text-inherit">FAQ</Link> {/* Corrected path */}
                <p className="mt-1">&copy; {new Date().getFullYear()} Your Site Name. All rights reserved.</p>
            </footer>
        </div>
        // Remove BrowserRouter wrapper here
    );
}

export default App; // Export the App component
